(()=>{const host=document.getElementById('routingInspector');if(!host)return;const text=v=>String(v||'').trim();function inspect(){const experiences=[...document.querySelectorAll('.experience')].map((el,index)=>{const name=text(el.querySelector('.exp-name')?.value)||`Experience ${index+1}`;const audience=[...(el.querySelector('.exp-audience')?.selectedOptions||[])].map(o=>({id:o.value,name:text(o.textContent)}));return{name,audience,index};});if(!experiences.length){host.innerHTML='<div class="routing-empty">Add an experience to see routing.</div>';return;}const fallback=experiences.filter(e=>!e.audience.length);const signatures=new Map();for(const e of experiences.filter(e=>e.audience.length)){const sig=e.audience.map(o=>o.id).sort().join('|');signatures.set(sig,[...(signatures.get(sig)||[]),e.name]);}const duplicate=[...signatures.values()].filter(v=>v.length>1);const rows=[...experiences].sort((a,b)=>{if(!a.audience.length&&b.audience.length)return 1;if(a.audience.length&&!b.audience.length)return-1;if(b.audience.length!==a.audience.length)return b.audience.length-a.audience.length;return a.index-b.index;}).map((e,rank)=>`<div class="routing-row"><span class="routing-rank">${rank+1}</span><div><strong>${e.name}</strong><small>${e.audience.length?`${e.audience.length} organization${e.audience.length===1?'':'s'}: ${e.audience.map(o=>o.name).join(', ')}`:'Fallback — used when no organization-specific experience matches'}</small></div><span class="routing-badge ${e.audience.length?'specific':'fallback'}">${e.audience.length?`${e.audience.length} org`:'Fallback'}</span></div>`).join('');const warnings=[];if(fallback.length>1)warnings.push('More than one fallback is configured. Publishing will be blocked.');if(duplicate.length)warnings.push('Two experiences use the same organization audience. Publishing will be blocked.');host.innerHTML=`<div class="routing-rule"><strong>Routing rule</strong><span>Most-specific matching audience wins. If two matches are equally specific, the experience configured first wins.</span></div>${warnings.map(w=>`<div class="routing-warning">${w}</div>`).join('')}<div class="routing-list">${rows}</div>`;}document.addEventListener('change',e=>{if(e.target.closest('.experience'))inspect();});document.addEventListener('input',e=>{if(e.target.matches('.exp-name'))inspect();});const observer=new MutationObserver(()=>inspect());observer.observe(document.getElementById('experiences'),{childList:true,subtree:true});window.addEventListener('DOMContentLoaded',()=>setTimeout(inspect,300));})();